import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Geo Blocking","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/geo-blocking.md","filePath":"openshield-xdp/user-guide/geo-blocking.md","lastUpdated":1785937469000}'),n={name:"openshield-xdp/user-guide/geo-blocking.md"};function o(r,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="geo-blocking" tabindex="-1">Geo Blocking <a class="header-anchor" href="#geo-blocking" aria-label="Permalink to &quot;Geo Blocking&quot;">​</a></h1><p>Since v2.2.0, OpenShield can block entire countries with a single keypress in the TUI. Blocking a country resolves its allocated IP ranges from MaxMind GeoLite2 data and enforces them as <strong>permanent subnet bans</strong> in the XDP LPM trie — packets from those ranges are dropped at the NIC, with zero per-packet userspace cost.</p><p><code>geoip.enabled</code> now defaults to <code>true</code> (since v2.2.0), so this works out of the box.</p><h2 id="blocking-a-country" tabindex="-1">Blocking a country <a class="header-anchor" href="#blocking-a-country" aria-label="Permalink to &quot;Blocking a country&quot;">​</a></h2><p>Open the TUI and press <code>0</code> for the geo tab:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  [B]lock Mode   [A]llow Mode</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   ●  CN</span></span>
<span class="line"><span>   ◌  RU        ← blocking in progress</span></span>
<span class="line"><span>   ✗  IR        ← failed (see notice line)</span></span>
<span class="line"><span>      US</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>Toggle the selected country (block → unblock)</td></tr><tr><td><code>b</code> / <code>a</code></td><td>Switch between block mode and allow-only mode</td></tr><tr><td><code>/</code></td><td>Search/filter the country list</td></tr><tr><td><code>j</code> / <code>k</code> or scroll wheel</td><td>Move through the list</td></tr><tr><td><code>Esc</code></td><td>Back to the dashboard</td></tr></tbody></table><ul><li>The <strong>first block downloads the GeoLite2 database</strong> (~30 MB), so it takes a few seconds — the status line tells you it&#39;s resolving ranges in the background.</li><li>While a block is being applied the country shows <code>◌</code>; a failure shows <code>✗</code> with the reason in the notice line.</li><li><strong>Unblocking is the same keypress again</strong> — the country&#39;s prefixes are removed from the trie by looking up its stored record, not by hunting individual IPs.</li></ul><h2 id="how-it-works-under-the-hood" tabindex="-1">How it works under the hood <a class="header-anchor" href="#how-it-works-under-the-hood" aria-label="Permalink to &quot;How it works under the hood&quot;">​</a></h2><ul><li>The country&#39;s allocated prefixes are resolved from the GeoLite2 database and inserted into the subnet-ban LPM trie with <strong>no expiry</strong> (permanent until you toggle it off).</li><li>Each geo ban carries a note like <code>geoblock: US (United States) — 241,377 prefixes — added 2026-08-05</code>, visible anywhere ban notes are shown, and the block record is persisted to disk so it <strong>survives loader restarts</strong>.</li><li>Blocked-country state is reapplied automatically on load — you configure it once in the TUI and it stays.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">geoip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # default: true since v2.2.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  license_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # empty = built-in default key; set your own MaxMind key to override</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  db_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/var/lib/openshield/GeoLite2-City.mmdb&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;block&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # &quot;block&quot; (block listed countries) or &quot;allow&quot; (allow ONLY listed)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  countries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># managed by the TUI geo tab — edit by hand only if you must</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  update_hours</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">168</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # GeoLite2 database refresh interval</span></span></code></pre></div><p>You don&#39;t need a MaxMind account: an empty <code>license_key</code> falls back to a built-in default key used for the GeoLite2 downloads. Set your own key if you prefer your own quota.</p><h2 id="accuracy-and-performance-caveats" tabindex="-1">Accuracy and performance caveats <a class="header-anchor" href="#accuracy-and-performance-caveats" aria-label="Permalink to &quot;Accuracy and performance caveats&quot;">​</a></h2><ul><li><strong>GeoIP is approximate.</strong> GeoLite2 country accuracy is roughly 99%, and anyone behind a VPN or proxy exits from wherever the exit node is. Treat geo blocking as a noise reducer, not a guarantee.</li><li><strong>Memory:</strong> a large country is on the order of 100–240k prefixes, which costs ~30 MB of BPF map memory in the LPM trie. Blocking several large countries at once adds up — watch map utilization on the TUI status screen.</li><li><strong>Speed:</strong> lookups happen in the kernel LPM trie alongside normal subnet-ban checks, so there is no per-packet userspace cost and no measurable latency added to the fast path.</li><li>Very large prefix lists are capped at the trie&#39;s per-country ceiling (largest prefixes kept); the block record notes when a country was truncated.</li></ul><h2 id="what-to-read-next" tabindex="-1">What to read next <a class="header-anchor" href="#what-to-read-next" aria-label="Permalink to &quot;What to read next&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/auto-fetch">Auto-Fetch Blocklists</a> — threat-intel feeds banned on a schedule</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/troubleshooting#where-do-i-look-when-something-weird-happened-during-an-attack">Attack Geo Analytics</a> — per-country breakdowns in attack reports</li><li><a href="/pingless-studios-docs/openshield-xdp/configuration/reference#geoip-geo-blocking">Full Config Reference — geoip</a></li></ul>`,17)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
